_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0453000" if __import__("os").path.isdir("./environment_mix/0453000") else "/app/database")
def open_library_get_book_by_title(title):
    import json, os
    db = json.load(open(os.path.join(_DB, 'openlibrary.json'), encoding='utf-8'))
    hits = [v for k, v in db['books_by_title'].items() if (title or '').lower() in k or k in (title or '').lower()]
    return {'numFound': len(hits), 'docs': hits}

_DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0453000" if __import__("os").path.isdir("./environment_mix/0453000") else "/app/database")
def open_library_get_authors_by_name(name):
    import json, os
    db = json.load(open(os.path.join(_DB, 'openlibrary.json'), encoding='utf-8'))
    nl = (name or '').lower()
    out = []
    for k, v in db['authors_by_name'].items():
        if k in nl or nl in k:
            out.extend(v)
    return {'numFound': len(out), 'docs': out}
